*----------------------------------------------------------
* sanebench.s - M9.1 (docs/8087.md): the SANE tool set as an
* 8087's arithmetic, tried and timed. A ProDOS 8 system file
* that starts SANE, runs a table of operations whose results
* the host judges (tools/sane_spike.py), then a table of
* loops that it times: both tables are generated by that tool
* (gen/vectors.s). Nothing of XT/GS is in it.
*
* The call (Apple Numerics Manual, 2nd ed., ch. 11, app. D):
*     PUSHLONG src | PUSHWORD value     (not every operation)
*     PUSHLONG dst
*     PUSHWORD opword     format in the high byte, operation low
*     LDX #$090A (FP816) or #$0B0A (Elems816) / JSL $E10000
* A is 0 and the carry clear after it; X, Y and the flags are
* the answer of a compare, a classify, a remainder.
*
* A vector (26 bytes; opword $FFFF ends the table):
*     +0  opword
*     +2  shape (low byte): 0 dst, 1 src and dst, 2 a word by
*         value and dst, 3 a word by value, 4 nothing;
*         high byte: 0 FP816, 1 Elems816
*     +4  the Environment word to begin with
*     +6  src, 10 bytes   +16  dst, 10 bytes
* and what is kept of it (18 bytes): dst, X, Y, P, and the
* Environment word after it.
*
* A timed loop (28 bytes; id 0 ends): id, opword, shape (and
* $80 in its low byte: no call, the loop alone), how many
* times, src, dst. SB_PHASE is written with the id as the loop
* begins and $FF as it ends: the host's tap takes the times.
*----------------------------------------------------------
 org $2000
 typ $FF
 dsk sanebench
TOOLS    = $E10000
SANE_DP  = $0900             ; SANE's direct page: a page of bank $00 of this program's

 mx %11
start
 jmp go
sb_magic   dw 0              ; $5A5A: done
sb_phase   dw 0              ; the loop under way
sb_ver     dw 0              ; SANEVersion
sb_err     dw 0              ; SANEStartUp's error
sb_nvec    dw 0              ; vectors run
go
 clc
 xce
 rep #$30
 mx %00
 ldx #$0201                ; TLStartUp
 jsl TOOLS
 ldx #$0203                ; MTStartUp
 jsl TOOLS
 pea SANE_DP
 ldx #$020A                ; SANEStartUp
 jsl TOOLS
 sta sb_err
 pha
 ldx #$040A                ; SANEVersion
 jsl TOOLS
 pla
 sta sb_ver
 jsr vectors
 jsr timing
 lda #$5A5A
 sta sb_magic
:hang
 bra :hang

*--- the vectors
vectors
 mx %00
 stz v_in
 stz v_out
:next
 ldx v_in
 lda vec_tab,x
 cmp #$FFFF
 bne :do
 rts
:do
 sta c_op
 lda vec_tab+2,x
 and #$00FF
 sta c_shape
 lda vec_tab+2,x
 xba
 and #$00FF
 sta c_elems
 lda vec_tab+4,x
 pha                       ; the Environment word: by value
 pea $0001                 ; FSETENV
 ldx #$090A
 jsl TOOLS
 ldx v_in
 ldy #0
:cp
 lda vec_tab+6,x
 sta srcbuf,y
 lda vec_tab+16,x
 sta dstbuf,y
 inx
 inx
 iny
 iny
 cpy #10
 bcc :cp
 jsr sane_call
 pea $0003                 ; FGETENV: the word in X
 ldx #$090A
 jsl TOOLS
 stx v_env
 ldx v_out
 ldy #0
:out
 lda dstbuf,y
 sta >OUTBUF,x
 inx
 inx
 iny
 iny
 cpy #10
 bcc :out
 lda vX
 sta >OUTBUF,x
 lda vY
 sta >OUTBUF+2,x
 lda vP
 sta >OUTBUF+4,x
 lda v_env
 sta >OUTBUF+6,x
 txa
 clc
 adc #8
 sta v_out
 lda v_in
 clc
 adc #26
 sta v_in
 inc sb_nvec
 jmp :next

*--- the timed loops
timing
 mx %00
 stz v_in
:next
 ldx v_in
 lda tim_tab,x
 bne :do
 rts
:do
 sta t_id
 lda tim_tab+2,x
 sta c_op
 lda tim_tab+4,x
 and #$007F
 sta c_shape
 lda tim_tab+4,x
 and #$0080
 sta c_null
 lda tim_tab+4,x
 xba
 and #$00FF
 sta c_elems
 lda tim_tab+6,x
 sta t_n
 ldy #0
:cp
 lda tim_tab+8,x
 sta srcbuf,y
 lda tim_tab+18,x
 sta t_dst,y
 inx
 inx
 iny
 iny
 cpy #10
 bcc :cp
 pea $0000                 ; the default environment
 pea $0001
 ldx #$090A
 jsl TOOLS
 lda t_id
 sta sb_phase
:loop
 lda t_dst
 sta dstbuf
 lda t_dst+2
 sta dstbuf+2
 lda t_dst+4
 sta dstbuf+4
 lda t_dst+6
 sta dstbuf+6
 lda t_dst+8
 sta dstbuf+8
 jsr sane_call
 dec t_n
 bne :loop
 lda #$00FF
 sta sb_phase
 lda v_in
 clc
 adc #28
 sta v_in
 jmp :next

*--- one call: c_op, c_shape, c_elems, srcbuf, dstbuf (c_null:
* everything but the call). vX, vY, vP: what it came back with.
sane_call
 mx %00
 tsc
 sta c_sp
 lda c_shape
 asl
 tax
 jmp (:shape,x)
:shape     da :dst,:both,:val,:word,:go
:both
 pea ^srcbuf
 pea srcbuf
:dst
 pea ^dstbuf
 pea dstbuf
 bra :go
:val
 lda srcbuf
 pha
 bra :dst
:word
 lda srcbuf
 pha
:go
 lda c_op
 pha
 lda c_null
 bne :null
 ldx #$090A
 lda c_elems
 beq :fp
 ldx #$0B0A
:fp
 jsl TOOLS
:back
 php
 stx vX
 sty vY
 sep #$20
 mx %10
 pla
 sta vP
 stz vP+1
 rep #$20
 mx %00
 rts
:null                      ; (what was pushed goes, as the tool would take it)
 mx %00
 lda c_sp
 tcs
 jsl nothing
 bra :back
nothing
 rtl

c_op       dw 0
c_shape    dw 0
c_elems    dw 0
c_null     dw 0
c_sp       dw 0
vX         dw 0
vY         dw 0
vP         dw 0
v_in       dw 0
v_out      dw 0
v_env      dw 0
t_id       dw 0
t_n        dw 0
t_dst      ds 10
srcbuf     ds 12
dstbuf     ds 12
 put gen/vectors
OUTBUF     ds 2              ; what is kept of the vectors, from here up (the host keeps the file below $BF00)
